const hosts = [...new Set(args.hosts)];
const results = max.batch([{tool: "maxops_fleet_overview", args: {}}, ...hosts.map(host => ({tool: "maxops_units_failed", args: {host}}))]);
const overview = results[0];
const ok = result => result.outcome === "succeeded" || result.outcome === "committed";
if (ok(overview) && !Array.isArray(overview.value?.hosts)) throw new Error("fleet.overview returned no hosts array");
const summary = {overview_outcome: overview.outcome, hosts: hosts.map((host, index) => {
  const observed = ok(overview) ? overview.value.hosts.find(row => row.host === host) : null;
  const failure = results[index + 1];
  if (ok(failure) && !Array.isArray(failure.value?.hosts)) throw new Error("units.failed returned no hosts array");
  const units = ok(failure) ? failure.value.hosts.find(row => row.host === host) : null;
  return {host, assessment: observed?.assessment ?? "unknown", agent: observed?.agent ?? null,
    exporter: observed?.exporter ?? null, units_outcome: failure.outcome,
    unit_scope: units?.unit_scope ?? null, units_state: units?.state ?? "unknown",
    failed_count: Array.isArray(units?.units) ? units.units.length : null,
    failed_units: Array.isArray(units?.units) ? units.units.slice(0, 50).map(unit => ({unit: unit.name ?? unit.unit ?? null, active_state: unit.active_state, sub_state: unit.sub_state})) : null,
    omitted_units: Array.isArray(units?.units) ? Math.max(0, units.units.length - 50) : 0,
    error: !ok(failure) ? failure.error : !ok(overview) ? overview.error : null};
})};
while (JSON.stringify(summary).length > 20000) {
  const row = [...summary.hosts].reverse().find(row => row.failed_units?.length);
  if (!row) throw new Error("fleet summary exceeds output budget");
  row.failed_units.pop(); row.omitted_units += 1;
}
return summary;
